function Message($store,$ws,$row,$headers,$idx,$cfg,$count){$lines=New-Object System.Collections.Generic.List[string];$lines.Add(([string]$cfg.message.title).Replace('{loja}',$store));$lines.Add('');if($cfg.message.includeRecordCount-and$count-gt1){$lines.Add("Registros no relatorio: $count");$lines.Add('')};$fields=@($cfg.message.fields);if($fields.Count-eq0){$fields=@();foreach($h in $headers){if($h-ne[string]$cfg.excel.storeColumn){$fields+=$h;if($fields.Count-ge[int]$cfg.message.maxAutoFields){break}}}};foreach($f in $fields){if($idx.ContainsKey([string]$f)){$v=[string]$ws.Cells.Item($row,[int]$idx[[string]$f]).Text;if(-not$v){$v='-'};$lines.Add(('{0}: {1}'-f$f,$v))}};return[string]::Join([Environment]::NewLine,$lines)}
function SendWA($chrome,$profile,$phone,$msg,$wait){$url='https://web.whatsapp.com/send?phone='+$phone+'&text='+[uri]::EscapeDataString($msg);Start-Process $chrome -ArgumentList("--user-data-dir=`"$profile`" --start-maximized `"$url`"")|Out-Null;Start-Sleep $wait;$sh=New-Object -ComObject WScript.Shell;$ok=$false;for($i=0;$i-lt8;$i++){if($sh.AppActivate('WhatsApp')){$ok=$true;break};Start-Sleep 1};if(-not$ok){throw 'Janela do WhatsApp nao encontrada.'};$sh.SendKeys('{ENTER}')}
function ProcessExcel($path,$cfg,$map,$chrome,$profile){$xl=$null;$wb=$null;$ws=$null;try{$xl=New-Object -ComObject Excel.Application;$xl.Visible=$false;$xl.DisplayAlerts=$false;$wb=$xl.Workbooks.Open($path,0,$true);if([string]$cfg.excel.worksheet){$ws=$wb.Worksheets.Item([string]$cfg.excel.worksheet)}else{$ws=$wb.Worksheets.Item(1)};$u=$ws.UsedRange;$rows=[int]$u.Rows.Count;$cols=[int]$u.Columns.Count;$headers=@();$idx=@{};for($c=1;$c-le$cols;$c++){$h=([string]$ws.Cells.Item(1,$c).Text).Trim();if(-not$h){$h="Coluna$c"};$headers+=$h;$idx[$h]=$c};$sc=[string]$cfg.excel.storeColumn;if(-not$idx.ContainsKey($sc)){throw "Coluna '$sc' nao encontrada."};$groups=@{};for($r=2;$r-le$rows;$r++){$s=NormStore $ws.Cells.Item($r,[int]$idx[$sc]).Value2;if(-not$s){continue};if(-not$groups.ContainsKey($s)){$groups[$s]=New-Object System.Collections.ArrayList};[void]$groups[$s].Add($r)};Log("Lojas encontradas no Excel: "+$groups.Count);$stamp=Get-Date -Format 'yyyyMMdd_HHmmss';foreach($s in($groups.Keys|sort)){$rr=$groups[$s];$out=Join-Path $StoreDir("{0}_{1}.xlsx"-f$s,$stamp);$ow=$xl.Workbooks.Add();$os=$ow.Worksheets.Item(1);for($c=1;$c-le$cols;$c++){$os.Cells.Item(1,$c).Value2=$headers[$c-1]};$or=2;foreach($sr in$rr){for($c=1;$c-le$cols;$c++){$os.Cells.Item($or,$c).Value2=$ws.Cells.Item($sr,$c).Value2};$or++};$ow.SaveAs($out,51);$ow.Close($false);if(-not$map.ContainsKey($s)){Log "$s sem telefone; arquivo separado criado." 'AVISO';continue};$phone=[string]$map[$s];$msg=Message $s $ws ([int]$rr[0]) $headers $idx $cfg $rr.Count;$preview=Join-Path $PreviewDir("{0}_{1}.txt"-f$s,$stamp);Set-Content $preview("Loja: $s`r`nTelefone: $phone`r`n`r`n$msg") -Encoding UTF8;if([bool]$cfg.whatsapp.dryRun){Write-Host '';Write-Host("PREVIA $s -> $phone") -ForegroundColor Yellow;Write-Host $msg;Log "$s preparado em DRY-RUN."}else{SendWA $chrome $profile $phone $msg ([int]$cfg.whatsapp.waitSeconds);Log "$s enviado.";Start-Sleep([int]$cfg.whatsapp.delayBetweenMessagesSeconds)}}}finally{if($wb){try{$wb.Close($false)}catch{}};if($xl){try{$xl.Quit()}catch{}};[GC]::Collect();[GC]::WaitForPendingFinalizers()}}
